INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(1,'星际穿越','Interstellar',2014,'科幻,冒险,剧情',169,9.4,240000,'克里斯托弗·诺兰','美国 / 英国','当时间成为距离，爱仍然指向同一个方向。一位父亲离开逐渐失去生机的地球，穿过虫洞寻找人类的新家园，也寻找与女儿重逢的可能。','/images/poster-1.jpg','/images/interstellar-backdrop.jpg',TRUE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(2,'沙丘2','Dune: Part Two',2024,'科幻,冒险',166,8.3,98000,'丹尼斯·维伦纽瓦','美国 / 加拿大','沙海之中，一个名字逐渐成为传说。保罗走进弗雷曼人的世界，在爱情、复仇与不可预测的命运之间做出选择。','/images/poster-2.jpg','/images/interstellar-backdrop.jpg',FALSE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(3,'布达佩斯大饭店','The Grand Budapest Hotel',2014,'喜剧,冒险,剧情',99,8.9,160000,'韦斯·安德森','美国 / 德国','一位礼宾员和年轻门童，在一幅名画引发的追逐中成为彼此的家人。粉色饭店里保存着一个时代最后的温柔与体面。','/images/poster-3.jpg','/images/interstellar-backdrop.jpg',FALSE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(4,'爱乐之城','La La Land',2016,'爱情,音乐,剧情',128,8.4,180000,'达米恩·查泽雷','美国','洛杉矶的黄昏里，演员与爵士乐手相遇。他们相互照亮，也在理想与生活的交叉口，学会如何告别。','/images/poster-4.jpg','/images/interstellar-backdrop.jpg',FALSE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(5,'千与千寻','Spirited Away',2001,'动画,奇幻,冒险',125,9.4,220000,'宫崎骏','日本','误入奇异小镇的千寻，必须在神灵的澡堂里找回自己的名字。一段关于勇气、记忆与成长的旅程，在列车驶向水面时悄然展开。','/images/poster-5.jpg','/images/interstellar-backdrop.jpg',FALSE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(6,'楚门的世界','The Truman Show',1998,'剧情,科幻',103,9.3,210000,'彼得·威尔','美国','楚门的生活看起来完美无缺，直到日常开始露出裂缝。当整个世界都在演出，一个普通人决定寻找自己的出口。','/images/poster-6.jpg','/images/interstellar-backdrop.jpg',FALSE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(7,'寄生虫','Parasite',2019,'剧情,悬疑',132,8.8,140000,'奉俊昊','韩国','两个家庭因一次家教机会产生交集。阶梯、雨水与气味，将看不见的阶层边界，一点一点变成无法回避的现实。','/images/poster-7.jpg','/images/interstellar-backdrop.jpg',FALSE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(8,'盗梦空间','Inception',2010,'科幻,悬疑,冒险',148,9.3,230000,'克里斯托弗·诺兰','美国 / 英国','梦境可以被进入，念头也可以被种下。一支团队潜入层层折叠的潜意识，而领队必须面对始终没有醒来的过去。','/images/poster-8.jpg','/images/interstellar-backdrop.jpg',FALSE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(9,'心灵奇旅','Soul',2020,'动画,音乐,奇幻',100,8.7,110000,'彼特·道格特','美国','一位爵士乐老师终于等到梦想中的演出，却意外走进灵魂的世界。他在另一段旅程里，重新认识了普通日子的光亮。','/images/poster-9.jpg','/images/interstellar-backdrop.jpg',FALSE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(10,'爆裂鼓手','Whiplash',2014,'音乐,剧情',107,8.7,120000,'达米恩·查泽雷','美国','年轻鼓手进入顶尖乐队，在掌声与苛责之间逼近自己的极限。每一次鼓点，都在追问卓越究竟需要付出什么。','/images/poster-10.jpg','/images/interstellar-backdrop.jpg',FALSE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(11,'降临','Arrival',2016,'科幻,剧情,悬疑',116,7.9,95000,'丹尼斯·维伦纽瓦','美国 / 加拿大','神秘飞船抵达地球，一位语言学家试着理解来访者的语言。随着符号被解开，她对时间与选择的认识也发生了变化。','/images/poster-11.jpg','/images/interstellar-backdrop.jpg',FALSE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(12,'寻梦环游记','Coco',2017,'动画,音乐,奇幻',105,9.1,190000,'李·昂克里奇','美国','热爱音乐的米格意外来到亡灵世界，踏上一段寻找家族故事的旅途。有些人离开了，但只要还被记得，就从未真正远去。','/images/poster-12.jpg','/images/interstellar-backdrop.jpg',FALSE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(13,'肖申克的救赎','The Shawshank Redemption',1994,'剧情',142,9.7,280000,'弗兰克·德拉邦特','美国','高墙将人生切成漫长的日子，安迪却始终保留着对自由的想象。友谊、耐心与希望，在最不可能的地方留下出口。','/images/poster-13.jpg','/images/interstellar-backdrop.jpg',FALSE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(14,'天使爱美丽','Amélie',2001,'爱情,喜剧',122,8.7,100000,'让-皮埃尔·热内','法国','在巴黎的小小咖啡馆，艾米丽开始悄悄改变身边人的生活。当她为别人制造幸福，也慢慢学会向自己的心意迈出一步。','/images/poster-14.jpg','/images/interstellar-backdrop.jpg',FALSE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(15,'火星救援','The Martian',2015,'科幻,冒险',144,8.5,130000,'雷德利·斯科特','美国 / 英国','被留在火星上的宇航员，用科学、幽默和一小片土豆田对抗绝境。在相隔数千万公里的两端，人们共同寻找回家的办法。','/images/poster-15.jpg','/images/interstellar-backdrop.jpg',FALSE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(16,'阿甘正传','Forrest Gump',1994,'剧情,爱情',142,9.5,250000,'罗伯特·泽米吉斯','美国','阿甘用自己的步伐穿过时代，也始终记得最初在乎的人。一段看似偶然的人生，串起执着、失去与朴素的爱。','/images/poster-16.jpg','/images/interstellar-backdrop.jpg',FALSE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(17,'2001太空漫游','2001: A Space Odyssey',1968,'科幻,冒险',149,8.9,85000,'斯坦利·库布里克','英国 / 美国','从荒原上的黑色石碑，到木星之外的未知空间，人类不断追问自身的起点与终点。一场留给眼睛、耳朵和想象力的远航。','/images/poster-17.jpg','/images/interstellar-backdrop.jpg',FALSE);
INSERT INTO movies(id,title,original_title,release_year,genres,runtime,rating,rating_count,director,country,synopsis,poster_url,backdrop_url,featured) VALUES(18,'蝙蝠侠：黑暗骑士','The Dark Knight',2008,'剧情,动作,悬疑',152,9.2,200000,'克里斯托弗·诺兰','美国 / 英国','哥谭在秩序与混乱之间摇摆。蝙蝠侠面对的不只是一个对手，还有那些让城市相信希望的规则，以及守护它们的代价。','/images/poster-18.jpg','/images/interstellar-backdrop.jpg',FALSE);
